function detectMissingSkills( 
    candidateSkills, 
    requiredSkills 
) { 
    const missingSkills = requiredSkills.filter( 
        skill => !candidateSkills.includes(skill) 
    ); 

    return missingSkills; 
} 

const candidateSkills = [ 
    "HTML", 
    "CSS", 
    "JavaScript" 
]; 

const requiredSkills = [ 
    "HTML", 
    "CSS", 
    "JavaScript", 
    "React", 
    "Node.js" 
]; 

const result = detectMissingSkills( 
    candidateSkills, 
    requiredSkills 
); 

console.log(result); 
