C. Matching Score Calculation 
function calculateMatch( 
    requiredSkills, 
    userSkills 
) { 
    if (requiredSkills.length === 0) { 
        return 0; 
    } 

    const matchedSkills = requiredSkills.filter( 
        skill => userSkills.includes(skill) 
    ); 

    const score = 
        (matchedSkills.length / 
        requiredSkills.length) * 100; 

    return score; 
} 











